B.aDq=new A.a("\u0644\u0642\u062f \u0627\u0633\u062a\u0637\u0627\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u062d\u0634\u062f \u062b\u0644\u0627\u062b\u064a\u0646 \u0623\u0644\u0641 \u0645\u0642\u0627\u062a\u0644 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0623\u0647\u0644 \u0645\u0643\u0629 \u0648\u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0648\u0644\u0642\u062f \u0623\u0639\u0644\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0649 \u063a\u064a\u0631 \u0639\u0627\u062f\u062a\u0647 \u0641\u064a \u063a\u0632\u0648\u0627\u062a\u0647 \u0647\u062f\u0641\u0647 \u0648\u0648\u062c\u0647\u062a\u0647 \u0641\u064a \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0625\u0630 \u0623\u0639\u0644\u0646 \u0635\u0631\u0627\u062d\u0629 \u0623\u0646\u0647 \u064a\u0631\u064a\u062f \u0642\u062a\u0627\u0644 \u0628\u0646\u064a \u0627\u0644\u0623\u0635\u0641\u0631 \u0627\u0644\u0631\u0648\u0645\u060c \u0639\u0644\u0645\u0627\u064b \u0628\u0623\u0646 \u0647\u062f\u064a\u0647 \u0641\u064a \u0645\u0639\u0638\u0645 \u063a\u0632\u0648\u0627\u062a\u0647 \u0623\u0646 \u064a\u0648\u0631\u0649 \u0641\u064a\u0647\u0627 \u0648\u0644\u0627\u064a\u0635\u0631\u062d \u0628\u0647\u062f\u0641\u0647 \u0648\u0648\u062c\u0647\u062a\u0647 \u0648\u0642\u0635\u062f\u0647 \u062d\u0641\u0627\u0638\u0627\u064b \u0639\u0644\u0649 \u0633\u0631\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0645\u0628\u0627\u063a\u062a\u0629 \u0627\u0644\u0639\u062f\u0648.",null)
B.b0L=new A.a("\u0648\u0627\u0633\u062a\u062f\u0644 \u0628\u0639\u0636 \u0627\u0644\u0639\u0644\u0645\u0627\u0621 \u0639\u0644\u0649 \u062c\u0648\u0627\u0632 \u0627\u0644\u062a\u0635\u0631\u064a\u062d \u0644\u062c\u0647\u0629 \u0627\u0644\u063a\u0632\u0648 \u0625\u0630\u0627 \u0644\u0645 \u062a\u0642\u062a\u0636\u064a \u0627\u0644\u0645\u0635\u0644\u062d\u0629 \u0633\u062a\u0631\u0647\u060c \u0648\u0642\u062f \u0635\u0631\u0651\u062d \ufdfa \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u063a\u0632\u0648\u0629 -\u0639\u0644\u0649 \u063a\u064a\u0631 \u0627\u0644\u0639\u0627\u062f\u0629- \u0628\u0627\u0644\u062c\u0647\u0629 \u0627\u0644\u062a\u064a \u064a\u0631\u064a\u062f \u063a\u0632\u0648\u0647\u0627 \u0648\u062c\u0644\u0651\u0649 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0644\u0623\u0633\u0628\u0627\u0628 \u0645\u0646\u0647\u0627:",null)
