B.azj=new A.a("\u0648\u0628\u0639\u062f \u062d\u0627\u062f\u062b\u0629 \u0623\u0628\u064a \u062c\u0646\u062f\u0644 \u0627\u0644\u0645\u0624\u0644\u0645\u0629 \u0627\u0644\u0645\u0624\u062b\u0631\u0629 \u0639\u0627\u062f \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0627\u0644\u0649 \u062a\u062c\u062f\u064a\u062f \u0627\u0644\u0645\u0639\u0627\u0631\u0636\u0629 \u0644\u0644\u0635\u0644\u062d\u060c \u0648\u0630\u0647\u0628\u062a \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0646\u0647\u0645 \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u064a\u0646\u0647\u0645 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0644\u0645\u0631\u0627\u062c\u0639\u062a\u0647\u060c \u0648\u0625\u0639\u0644\u0627\u0646 \u0645\u0639\u0627\u0631\u0636\u062a\u0647\u0645 \u0645\u062c\u062f\u062f\u0627\u064b \u0644\u0644\u0635\u0644\u062d \u0625\u0644\u0627 \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0645\u0627 \u0623\u0639\u0637\u0627\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0635\u0628\u0631 \u0648\u062d\u0643\u0645\u0629 \u0648\u062d\u0644\u0645 \u0648\u0642\u0648\u0629 \u062d\u062c\u0629 \u0627\u0633\u062a\u0637\u0627\u0639 \u0623\u0646 \u064a\u0642\u0646\u0639 \u0627\u0644\u0645\u0639\u0627\u0631\u0636\u064a\u0646 \u0628\u0648\u062c\u0627\u0647\u0629 \u0627\u0644\u0635\u0644\u062d\u060c \u0648\u0623\u0646\u0647 \u0641\u064a \u0635\u0627\u0644\u062d \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0623\u0646\u0647 \u0646\u0635\u0631 \u0644\u0647\u0645\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u062c\u0639\u0644 \u0644\u0644\u0645\u0633\u062a\u0636\u0639\u0641\u064a\u0646 \u0645\u0646 \u0623\u0645\u062b\u0627\u0644 \u0627\u0628\u064a \u062c\u0646\u062f\u0644 \u0641\u0631\u062c\u0627\u064b \u0648\u0645\u062e\u0631\u062c\u0627\u064b \u0648\u0642\u062f \u062a\u062d\u0642\u0642 \u0645\u0627 \u0623\u062e\u0628\u0631 \u0628\u0647 \ufdfa .",null)
B.b2U=new A.a("\u0648\u0628\u0647\u0630\u0627 \u064a\u062a\u0628\u064a\u0646 \u0623\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0636\u0639 \u0642\u0627\u0639\u062f\u0629 \u0627\u062d\u062a\u0631\u0627\u0645 \u0627\u0644\u0645\u0639\u0627\u0631\u0636\u0629 \u0627\u0644\u0646\u0632\u064a\u0647\u0629 \u062d\u064a\u062b \u0642\u0631\u0631 \u0630\u0644\u0643 \u0628\u0642\u0648\u0644\u0647 \u0648\u0641\u0639\u0644\u0647 \u0648\u0647\u0648 \u2013 \u0648\u0627\u0644\u0644\u0647 \u0623\u0639\u0644\u0645 - \u0625\u0646\u0645\u0627 \u0623\u0631\u0627\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0641\u0639\u0644 \u0627\u0631\u0634\u0627\u062f \u0627\u0644\u0642\u0627\u062f\u0629 \u0645\u0646 \u0628\u0639\u062f\u0647 \u0627\u0644\u0649 \u0627\u062d\u062a\u0631\u0627\u0645 \u0627\u0644\u0645\u0639\u0627\u0631\u0636\u0629 \u0627\u0644\u0646\u0632\u064a\u0647\u0629 \u0627\u0644\u062a\u064a \u062a\u0635\u062f\u0631 \u0645\u0646 \u0623\u062a\u0628\u0627\u0639\u0647\u0645\u060c \u0648\u0630\u0644\u0643 \u0628\u062a\u0634\u062c\u064a\u0639 \u0627\u0644\u0623\u062a\u0628\u0627\u0639 \u0639\u0644\u0649 \u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0622\u0631\u0627\u0621 \u0627\u0644\u0633\u0644\u064a\u0645\u0629 \u0627\u0644\u062a\u064a \u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0639\u0627\u0645\u0629.",null)
B.aWO=new A.a("\u0648\u0647\u0630\u0627 \u0627\u0644\u0647\u062f\u064a \u0627\u0644\u0646\u0628\u0648\u064a \u0627\u0644\u0643\u0631\u064a\u0645 \u0628\u064a\u0646 \u0623\u0646 \u062d\u0631\u064a\u0629 \u0627\u0644\u0631\u0623\u064a \u0645\u0643\u0641\u0648\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0627\u0633\u0644\u0627\u0645\u064a\u060c \u0648\u0623\u0646 \u0644\u0644\u0641\u0631\u062f \u0641\u064a \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u0633\u0644\u0645 \u0627\u0644\u062d\u0631\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0639\u0646 \u0631\u0623\u064a\u0647\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u0623\u064a \u0646\u0642\u062f\u0627\u064b \u0644\u0645\u0648\u0642\u0641 \u062d\u0627\u0643\u0645 \u0645\u0646 \u0627\u0644\u062d\u0643\u0627\u0645 \u0623\u0648 \u062e\u0644\u064a\u0641\u0629 \u0645\u0646 \u0627\u0644\u062e\u0644\u0641\u0627\u0621\u060c \u0641\u0645\u0646 \u062d\u0642 \u0627\u0644\u0641\u0631\u062f \u0627\u0644\u0645\u0633\u0644\u0645 \u0623\u0646 \u064a\u0628\u064a\u0646 \u0648\u062c\u0647\u0629 \u0646\u0638\u0631\u0647 \u0641\u064a \u062c\u0648 \u0645\u0646 \u0627\u0644\u0623\u0645\u0646 \u0648\u0627\u0644\u0623\u0645\u0627\u0646 \u062f\u0648\u0646 \u0627\u0631\u0647\u0627\u0628 \u0623\u0648 \u062a\u0633\u0644\u0637 \u064a\u062e\u0646\u0642 \u062d\u0631\u064a\u0629 \u0627\u0644\u0643\u0644\u0645\u0629 \u0648\u0627\u0644\u0641\u0643\u0631.",null)
