B.aWD=new A.a("\u0648\u0645\u0627\u062c\u0631\u0649 \u0628\u064a\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u0623\u0628\u064a \u062c\u0647\u0644 \u0648\u0647\u0648 \u0641\u064a \u0627\u0644\u0631\u0645\u0642 \u0627\u0644\u0623\u062e\u064a\u0631 \u0645\u0646 \u0627\u0644\u062d\u0648\u0627\u0631 \u0641\u064a\u0647 \u0639\u0628\u0631\u0629 \u0628\u0644\u064a\u063a\u0629 \u0641\u0647\u0630\u0627 \u0627\u0644\u0637\u0627\u063a\u064a\u0629 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0634\u062f\u064a\u062f \u0627\u0644\u0623\u0630\u0649 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0645\u0643\u0629 \u0642\u062f \u0648\u0642\u0639 \u0635\u0631\u064a\u0639\u0627\u064b \u0628\u064a\u0646 \u0623\u064a\u062f\u064a \u0645\u0646 \u0643\u0627\u0646 \u064a\u0624\u0630\u064a\u0647\u0645 \u0648\u064a\u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0630\u064a \u064a\u0642\u0636\u064a \u0639\u0644\u0649 \u0622\u062e\u0631 \u0631\u0645\u0642 \u0645\u0646 \u062d\u064a\u0627\u062a\u0647 \u0647\u0648 \u0623\u062d\u062f \u0627\u0644\u0645\u0633\u062a\u0636\u0639\u0641\u064a\u0646 \u0648\u0644\u0642\u062f \u0643\u0627\u0646 \u0623\u0628\u0648 \u062c\u0647\u0644 \u0645\u0633\u062a\u0643\u0628\u0631\u0627\u064b \u062c\u0628\u0627\u0631\u0627\u064b \u062d\u062a\u0649 \u0648\u0647\u0648 \u0635\u0631\u064a\u0639 \u0648\u0641\u064a \u0622\u062e\u0631 \u0644\u062d\u0638\u0627\u062a \u062d\u064a\u0627\u062a\u0647 \u0641\u0642\u062f \u062c\u0627\u0621 \u0641\u064a \u0631\u0648\u0627\u064a\u0629 \u0644\u0627\u0628\u0646 \u0625\u0633\u062d\u0627\u0642 \u0623\u0646\u0647 \u0642\u0627\u0644 \u0644\u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0644\u0645\u0627 \u0623\u0631\u0627\u062f \u0623\u0646 \u064a\u062d\u062a\u0632\u0651\u064e \u0631\u0623\u0633\u0647 \u0641\u0642\u0627\u0644 : \u0644\u0642\u062f \u0627\u0631\u062a\u0642\u064a\u062a \u0645\u0631\u062a\u0642\u0649\u064b \u0635\u0639\u0628\u0627\u064b \u064a\u0627 \u0631\u0648\u064a\u0639\u064a \u0627\u0644\u063a\u0646\u0645.",null)
B.aLK=new A.a("\u0641\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0645 \u064a\u0639\u062c\u0651\u0650\u0644 \u0644\u0647\u0630\u0627 \u0627\u0644\u062e\u0628\u064a\u062b \u0623\u0628\u064a \u062c\u0647\u0644 \u0628\u0636\u0631\u0628\u0627\u062a \u0627\u0644\u0623\u0628\u0637\u0627\u0644 \u0645\u0646 \u0623\u0634\u0628\u0627\u0644 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u0644\u0643\u0646\u0647 \u0623\u0628\u0642\u0627\u0647 \u0645\u0635\u0631\u0648\u0639\u0627\u064b \u0641\u064a \u062d\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0625\u062f\u0631\u0627\u0643 \u0648\u0627\u0644\u0648\u0639\u064a \u0628\u0639\u062f \u0623\u0646 \u0623\u0635\u0627\u0628\u062a\u0647 \u0636\u0631\u0628\u0627\u062a \u0623\u0634\u0641\u064e\u062a\u0652 \u0628\u0647 \u0639\u0644\u0649 \u0627\u0644\u0647\u0644\u0627\u0643 \u0627\u0644\u0623\u0628\u062f\u064a \u0644\u064a\u0631\u064a\u0647 \u0628\u0639\u064a\u0646 \u0628\u0635\u0631\u0647 \u0645\u0627\u0628\u0644\u063a\u0647 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u0646\u0629 \u0648\u0627\u0644\u0630\u0644 \u0648\u0627\u0644\u062e\u0630\u0644\u0627\u0646 \u0639\u0644\u0649 \u064a\u062f \u0645\u0646 \u0643\u0627\u0646 \u064a\u0633\u062a\u0636\u0639\u0641\u0647 \u0648\u064a\u0624\u0630\u064a\u0647 \u0648\u064a\u0636\u0637\u0647\u062f\u0647 \u0628\u0645\u0643\u0629 \u0645\u0646 \u0631\u062c\u0627\u0644 \u0627\u0644\u0631\u0639\u064a\u0644 \u0627\u0644\u0623\u0648\u0644 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0627\u0644\u0649 \u0645\u0638\u0644\u0651\u064e\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0637\u0647\u0631 \u0627\u0644\u0639\u0642\u064a\u062f\u0629 \u0648\u0627\u0644\u062a\u0639\u0628\u062f \u0644\u0644\u0647 \u0628\u0634\u0631\u0627\u0626\u0639\u0647 \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0631\u062d\u0645\u0629 \u0644\u0644\u0639\u0627\u0644\u0645\u064a\u0646\u060c \u0641\u0647\u0630\u0627 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a\u0639\u0644\u0648 \u0639\u0644\u0649 \u0635\u062f\u0631\u0647 \u0648\u064a\u062f\u0648\u0633\u0647 \u0628\u0642\u062f\u0645\u064a\u0647 \u0648\u064a\u0642\u0628\u0636 \u0639\u0644\u0649 \u0644\u062d\u064a\u062a\u0647 \u062a\u062d\u0642\u064a\u0631\u0627\u064b \u0644\u0647 \u0648\u064a\u0642\u0631\u0651\u0650\u0639\u0647 \u062a\u0642\u0631\u064a\u0639\u0627\u064b \u064a\u0628\u0644\u063a \u0645\u0646 \u0646\u0641\u0633\u0647 \u0645\u062c\u0645\u0639 \u063a\u0631\u0648\u0631\u0647 \u0648\u0627\u0633\u062a\u0643\u0628\u0627\u0631\u0647 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u064a\u0633\u062a\u0644 \u0645\u0646\u0647 \u0633\u064a\u0641\u0647 \u0625\u0645\u0639\u0627\u0646\u0627\u064b \u0641\u064a \u0627\u0644\u0628\u0637\u0634 \u0628\u0647\u060c \u0641\u064a\u0642\u062a\u0644\u0647 \u0628\u0647 \u0648\u064a\u0645\u0639\u0646 \u0641\u064a \u0625\u063a\u0627\u0638\u062a\u0647 \u0628\u0625\u062e\u0628\u0627\u0631\u0647 \u0623\u0646 \u0627\u0644\u0646\u0635\u0631 \u0639\u0642\u062f \u0628\u0646\u0627\u0635\u064a\u0629 \u062c\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0623\u0646 \u0634\u0646\u0627\u0631 \u0627\u0644\u0647\u0632\u064a\u0645\u0629 \u0627\u0644\u0646\u0643\u0631\u0627\u0621 \u0648\u0639\u0627\u0631\u0647\u0627 \u0648\u062e\u0632\u064a\u0647\u0627 \u0648\u062e\u0630\u0644\u0627\u0646\u0647\u0627 \u0642\u062f \u0631\u0632\u0626\u062a \u0628\u0647 \u0643\u062a\u0627\u0626\u0628 \u0627\u0644\u063a\u0631\u0648\u0631 \u0627\u0644\u0623\u062c\u0648\u0641 \u0641\u064a \u062d\u0634\u0648\u062f \u0627\u0644\u0646\u0641\u064a\u0631 \u0627\u0644\u0630\u064a \u0642\u0627\u062f\u0647 \u0647\u0630\u0627 \u0627\u0644\u0643\u0641\u0648\u0631 \u0627\u0644\u062e\u0628\u064a\u062b.",null)
